import argparse
import sys

def parse_subparser_arguments(unparsed_arguments, subparsers):
    if not isinstance(unparsed_arguments, list):
        raise TypeError("unparsed_arguments must be a list")
    if not isinstance(subparsers, dict):
        raise TypeError("subparsers must be a dictionary")

    parsed_results = {}
    remaining_arguments = unparsed_arguments[:]

    for subparser_name, subparser in subparsers.items():
        if not isinstance(subparser, argparse.ArgumentParser):
            raise TypeError(f"Subparser for {subparser_name} must be an argparse.ArgumentParser instance")

        try:
            parsed_namespace, unparsed = subparser.parse_known_args(remaining_arguments)
            parsed_results[subparser_name] = parsed_namespace
            remaining_arguments = unparsed
        except argparse.ArgumentError as e:
            print(f"Error parsing arguments for subparser '{subparser_name}': {e}", file=sys.stderr)
        except Exception as e:
            print(f"Unexpected error: {e}", file=sys.stderr)

    return parsed_results, remaining_arguments

