import sys

def run_borgmatic():
    try:
        result = subprocess.run(
            [sys.executable, '-m', 'borgmatic', '--help'],
            capture_output=True,
            text=True,
            check=True
        )
        return result.stdout
    except subprocess.CalledProcessError:
        return ""

def parse_borgmatic_help(help_output):
    parser = argparse.ArgumentParser(add_help=False)
    parser.add_argument('args', nargs=argparse.REMAINDER)
    return parser.parse_args(help_output.split())

def create_borgmatic_parser(borgmatic_args):
    parser = argparse.ArgumentParser(add_help=False)
    subparsers = parser.add_subparsers(dest='subcommand')

    for action in borgmatic_args._actions:
        if isinstance(action, argparse._SubParsersAction):
            for choice, subparser in action.choices.items():
                subparser_parser = argparse.ArgumentParser(add_help=False)
                subparser._add_arguments(subparser_parser)
                subparsers.add_parser(choice, parents=[subparser_parser])

    return parser

def get_completions(parser, args):
    if args.subcommand:
        subparser = parser.choices[args.subcommand]
        subparser_parser = argparse.ArgumentParser(add_help=False)
        subparser._add_arguments(subparser_parser)
        return subparser_parser.format_usage().split()[1:]
    return []

def bash_completion():
    borgmatic_help = run_borgmatic()
    borgmatic_args = parse_borgmatic_help(borgmatic_help)
    parser = create_borgmatic_parser(borgmatic_args)

    args, _ = parser.parse_known_args()
    completions = get_completions(parser, args)

    print('\n'.join(completions))

