import argparse

def parse_arguments(*arguments):
    parser = argparse.ArgumentParser()
    for arg in arguments:
        if '=' not in arg:
            raise ValueError(f"Argument '{arg}' is not in the expected 'name=value' format.")

        name, value = arg.split('=', 1)
        try:
            int_value = int(value)
            parser.add_argument(f'--{name}', type=int, default=int_value)
        except ValueError:
            try:
                float_value = float(value)
                parser.add_argument(f'--{name}', type=float, default=float_value)
            except ValueError:
                parser.add_argument(f'--{name}', default=value)
    return parser.parse_args()

