def make_parsers(subcommands=None):
    if subcommands is None:
        subcommands = {}

    parser = argparse.ArgumentParser(description='Main parser')
    subparsers = parser.add_subparsers(dest='command')

    for name, options in subcommands.items():
        subparser = subparsers.add_parser(name, help=options.get('help', ''))
        for opt, opt_config in options.get('arguments', {}).items():
            subparser.add_argument(opt, **opt_config)

    return parser, subparsers

