class InventoryValidator:
    INVALID_VERSION_ERROR = "Invalid prior version"

    def __init__(self, version, data):
        self.version = version
        self.data = data

    def error(self, message=INVALID_VERSION_ERROR):
        return message

    def validate_as_prior_version(self, prior: 'InventoryValidator') -> str:
        if not isinstance(prior, InventoryValidator):
            return self.error()

        if not self._is_version_valid(prior.version):
            return self.error()

        if not self._is_data_consistent(prior.data):
            return self.error()

        return None

    def _is_version_valid(self, prior_version) -> bool:
        return prior_version < self.version

    def _is_data_consistent(self, prior_data) -> bool:
        return all(
            key in self.data and self.data[key] == prior_data[key]
            for key in prior_data
        )

def get_logical_path_map(inventory, version):
    if not isinstance(inventory, list):
        raise TypeError("Inventory must be a list.")
    if not isinstance(version, (str, int, float)):
        raise TypeError("Version must be a string, integer, or float.")

    path_map = {}
    for item in inventory:
        if isinstance(item, dict):
            item_version = item.get('version')
            item_name = item.get('name')
            item_path = item.get('path')
            if item_version == version and item_name is not None and item_path is not None:
