def _eval_file(prefix, file_path):
    if not file_path.startswith(prefix) or file_path.endswith(f'.{XML_EXTENSION}'):
        return None

    extension = os.path.splitext(file_path)[-1].lower().strip('.')
    component_id = os.path.basename(file_path).split('.')[0]

    if extension == PDF_EXTENSION:
        return {component_id: file_path}
    else:
        return {component_id: file_path, 'ftype': extension}

