XML_EXTENSION = '.xml'

def group_xml_files_by_base_name(zip_path):
    xml_file_groups = defaultdict(list)

    try:
        with ZipFile(zip_path, 'r') as zip_ref:
            for file_info in zip_ref.infolist():
                if file_info.filename.endswith(XML_EXTENSION):
                    base_name = os.path.splitext(file_info.filename)[0]
                    xml_file_groups[base_name].append(file_info.filename)
    except FileNotFoundError:
        print(f"Error: The file {zip_path} was not found.")
    except BadZipFile:
        print(f"Error: The file {zip_path} is not a valid zip file.")

    return xml_file_groups

def _explore_zipfile(zip_path):
