def match_pubdate(node, pubdate_xpaths):
    if not isinstance(pubdate_xpaths, list):
        raise TypeError("pubdate_xpaths should be a list of XPath expressions.")

    if not hasattr(node, 'xpath'):
        raise TypeError("node must be an lxml.etree._Element with an 'xpath' method.")

    for xpath in pubdate_xpaths:
        if not isinstance(xpath, str):
            raise TypeError("Each item in pubdate_xpaths should be a string.")

