class ExpressionProcessor:
    ZERO = '0'
    ONE = '1'

    def absorb(self, args):
        def absorb_rule(a, b):
            if a == self.ZERO:
                return b
            if b == self.ZERO:
                return a
            if a == self.ONE and b == self.ZERO:
                return self.ZERO
            if a == self.ZERO and b == self.ONE:
                return self.ZERO
            if a == b:
                return a
            return (a, b)

        absorbed = []
        for expr in args:
            if isinstance(expr, tuple) and len(expr) == 2:
                a, b = expr
                if isinstance(a, str) and isinstance(b, str):
                    absorbed.append(absorb_rule(a, b))
                else:
                    absorbed.append(expr)
            else:
                absorbed.append(expr)
        return absorbed

class HookRegistry:
    def __init__(self):
        self._registry = {}

    def add_handler(self, hook):
        def decorator(func):
            if hook not in self._registry:
                self._registry[hook] = []
            self._registry[hook].append(func)
            return func
        return decorator

    def trigger(self, hook):
        if hook in self._registry:
            for func in self._registry[hook]:
                func()
        else:
            print(f"No handlers registered for {hook}")

