def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    for field, schema in observer_schema.items():
        if field not in response:
            raise KeyError(f"Field '{field}' not present in the response")

        if field not in last_applied_manifest:
            if isinstance(schema, dict):
                last_applied_manifest[field] = {}
                update_last_applied_manifest_dict_from_resp(last_applied_manifest[field], schema, response[field])
            else:
                last_applied_manifest[field] = response[field]
        elif isinstance(last_applied_manifest[field], dict) and isinstance(schema, dict):
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[field], schema, response[field])
        else:
            last_applied_manifest[field] = response[field]

from typing import Any, List, Union

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest: List[Union[Any, List[Any]]], 
    observer_schema: List[Any], 
    response: List[Any]
) -> None:
    if not observer_schema or not response:
        return

    for i, schema in enumerate(observer_schema):
        if i >= len(response):
            if len(last_applied_manifest) <= i:
                last_applied_manifest.append(None)
            continue

        if isinstance(schema, list):
            if len(last_applied_manifest) <= i or not isinstance(last_applied_manifest[i], list):
                last_applied_manifest.append([])

            update_last_applied_manifest_list_from_resp(
                last_applied_manifest[i], schema, response[i]
            )
        elif isinstance(response[i], list):
            raise ValueError("Schema mismatch: expected non-list, got list")
        else:
            if len(last_applied_manifest) <= i:
                last_applied_manifest.append(None)

            last_applied_manifest[i] = response[i]

