    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            result_dict[key] = generate_default_observer_schema_dict(value, first_level)
        elif isinstance(value, list):
            result_dict[key] = [
                generate_default_observer_schema_dict(item, first_level) if isinstance(item, dict) else None
                for item in value
            ]
        else:
            result_dict[key] = None

        if first_level:
