class Histogram:
    def __init__(self, min_edge: float, max_edge: float, bins: int):
        if bins <= 0:
            raise ValueError("Number of bins must be positive.")
        self.min_edge = min_edge
        self.max_edge = max_edge
        self.bins = bins
        self.bin_width = (max_edge - min_edge) / bins
        self.histogram = [0.0] * bins

    def fill(self, coord: float, weight: float = 1.0):
        if self.min_edge <= coord <= self.max_edge:
            index = int((coord - self.min_edge) / self.bin_width)
            if index == self.bins:  # Handle edge case where coord is exactly max_edge
                index -= 1
            self.histogram[index] += weight

def difference(d1, d2, level=-1):
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise ValueError("Both arguments must be dictionaries.")

    def diff_dicts(d1, d2, level):
        result = {}
        for k, v in d1.items():
            if k not in d2:
                result[k] = v
            elif isinstance(v, dict) and isinstance(d2[k], dict):
                nested_diff = diff_dicts(v, d2[k], level - 1)
                if nested_diff:
                    result[k] = nested_diff
            elif level!= 0 and isinstance(v, (list, set)) and isinstance(d2[k], type(v)):
                nested_diff = type(v)(item for item in v if item not in d2[k])
                if nested_diff:
                    result[k] = nested_diff
        return result

    return diff_dicts(d1, d2, level)

