import numbers

class Histogram:
    ZERO = 0

    def __init__(self):
        self._scale = None
        self._data = []

    def compute_scale(self):
        return sum(self._data)

    def get_scale(self, recompute):
        if self._scale is None or recompute:
            self._scale = self.compute_scale()
        return self._scale

    def set_scale(self, other):
        if self._scale == self.ZERO:
            raise ValueError("Histograms with scale equal to zero can't be rescaled.")
        self._scale = other

    def scale(self, other=None, recompute=False):
        if other is None:
            return self.get_scale(recompute)
        elif isinstance(other, numbers.Number):
            if self._scale is not None and self._scale!= self.ZERO:
                self.set_scale(other / self.get_scale(recompute))
            else:
                self.set_scale(other)
        else:
            raise TypeError("Other must be None or a number.")

