class Graph:
    def __init__(self, points):
        self.points = points

    def to_csv(self, separator=",", header=None):
        if not isinstance(self.points, (list, tuple)):
            raise ValueError("Points must be a list or tuple.")

        output = io.StringIO()
        writer = csv.writer(output, delimiter=separator)

        if header is not None:
            writer.writerow([header])

        for point in self.points:
            if not isinstance(point, (list, tuple)):
                raise ValueError("Each point must be a list or tuple.")
            row = []
            for coord in point:
                if isinstance(coord, (list, tuple)):
                    row.extend(map(str, coord))
                else:
                    row.append(str(coord))
            writer.writerow(row)

        return output.getvalue()

