def hist_to_graph(hist, make_value=None, get_coordinate=LEFT,
                  field_names=("x", "y"), scale=None):
    if make_value is None:
        make_value = lambda bin_: bin_.content

    graph_points = []
    coordinate_mapping = {
        LEFT: lambda bin_: bin_.left,
        RIGHT: lambda bin_: bin_.right,
        MIDDLE: lambda bin_: (bin_.left + bin_.right) / 2
    }

    if get_coordinate not in coordinate_mapping:
        raise ValueError("Invalid get_coordinate value")

    for bin_ in hist:
        x = coordinate_mapping[get_coordinate](bin_)
        value = make_value(bin_)

        if isinstance(value, tuple):
            if len(value)!= len(field_names):
                raise ValueError("Length of value tuple does not match field_names")
            point = {field_names[i]: value[i] for i in range(len(value))}
        else:
            point = {field_names[0]: x, field_names[1]: value}

        graph_points.append(point)

    graph = {"points": graph_points}

    if scale is True and hasattr(hist,'scale'):
        graph["scale"] = hist.scale
    elif scale is not None:
        graph["scale"] = scale

    return graph

