class MyDateParser:
    def parse(self, timestr: str, default: datetime = None, ignoretz: bool = False, tzinfos = None, **kwargs) -> datetime:
        if not isinstance(timestr, str):
            raise TypeError("Input must be a string.")

        parsed_datetime = self._parse_with_default(timestr, default, **kwargs)

        if tzinfos and not ignoretz:
            parsed_datetime = self._apply_tzinfos(parsed_datetime, tzinfos)

        if ignoretz and parsed_datetime.tzinfo is not None:
            parsed_datetime = parsed_datetime.replace(tzinfo=None)

        return parsed_datetime

    def _parse_with_default(self, timestr: str, default: datetime, **kwargs) -> datetime:
        if isinstance(default, datetime):
            return du_parse(timestr, default=default, **kwargs)
        return du_parse(timestr, **kwargs)

    def _apply_tzinfos(self, parsed_datetime: datetime, tzinfos) -> datetime:
        if isinstance(tzinfos, dict):
            def tzinfos_func(tzname, tzoffset):
                return tzinfos.get(tzname) or tzoffset
        elif callable(tzinfos):
            tzinfos_func = tzinfos
        else:
            raise ParserError("Invalid tzinfos argument.")

        if parsed_datetime.tzinfo is not None:
            tzname = parsed_datetime.tzinfo.tzname(parsed_datetime)
            tz = tzinfos_func(tzname, parsed_datetime.tzinfo)
            if isinstance(tz, (int, float)):
                tz = tzoffset(None, tz)
            parsed_datetime = parsed_datetime.astimezone(tz)
        return parsed_datetime

