from zope.interface import Interface, InterfaceClass, providedBy, Invalid
from inspect import signature, Signature, getmembers, isfunction, ismethod

def _verify(iface, candidate, tentative=False, vtype=None):
    errors = []

    if not isinstance(iface, (Interface, InterfaceClass)):
        raise Invalid("Invalid interface type")

    if not tentative and not providedBy(candidate).isOrExtends(iface):
        errors.append(f"{candidate} does not provide the interface {iface}")

    iface_methods = {name for name, _ in getmembers(iface, isfunction)}
    candidate_methods = {name for name, _ in getmembers(candidate, ismethod)}

    for method_name in iface_methods:
        iface_method = getattr(iface, method_name, None)
        candidate_method = getattr(candidate, method_name, None)

        if candidate_method is None:
            errors.append(f"Missing method: {method_name}")
        elif not callable(candidate_method):
            errors.append(f"{method_name} is not callable")
        else:
            iface_signature = signature(iface_method)
            candidate_signature = signature(candidate_method)

            if iface_signature!= candidate_signature:
                errors.append(f"Signature mismatch for method {method_name}: "
                              f"expected {iface_signature}, got {candidate_signature}")

    iface_attrs = {name for name, _ in getmembers(iface) if not isfunction(getattr(iface, name, None))}
    candidate_attrs = {name for name, _ in getmembers(candidate) if not ismethod(getattr(candidate, name, None))}

    for attr_name in iface_attrs:
        if attr_name not in candidate_attrs:
            errors.append(f"Missing attribute: {attr_name}")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True

from zope.interface import InterfaceClass, Invalid, implementer
from zope.interface.verify import verifyClass

def verify_interface_compliance(iface, candidate, tentative=False):
    errors = []

    # Check if the candidate claims to provide the interface
    if not tentative and not iface.providedBy(candidate):
        errors.append(f"Object {candidate} does not claim to provide interface {iface}")

    # Verify that the candidate's class implements the interface
    try:
        verifyClass(iface, type(candidate))
    except Invalid as e:
        errors.extend(e.args[0].split('\n') if e.args else [str(e)])

    # Collect all errors
    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid('\n'.join(errors))

    return True

import inspect
from abc import ABC

def verifyClass(iface, candidate, tentative=False):
    if not inspect.isclass(iface) or not inspect.isabstract(iface):
        return False
    if not inspect.isclass(candidate):
        return False

    required_methods = iface.__abstractmethods__
    for method in required_methods:
        if not hasattr(candidate, method):
            return False
        if tentative:
            return True
        if not callable(getattr(candidate, method)):
            return False
    return True

def is_single_metaclass(metaclasses):
    return len(metaclasses) == 1

def raise_conflict_error(bases):
    raise TypeError("Cannot create a consistent method resolution "
                    "order (MRO) for bases %r" % (bases,))

def determineMetaclass(bases, explicit_mc=None):
    if explicit_mc is not None:
        return explicit_mc

    if not bases:
        return type

    metaclasses = {type(base) for base in bases if type(base) is not type}

    if is_single_metaclass(metaclasses):
        return metaclasses.pop()
    elif len(metaclasses) > 1:
        raise_conflict_error(bases)
    else:
        return type

def minimalBases(classes):
    if not isinstance(classes, dict):
        raise ValueError("Input must be a dictionary")

    all_class_names = set()
    all_subclass_names = set()

    for cls, subs in classes.items():
        if not isinstance(subs, (set, list)):
            raise ValueError("Subclasses must be a set or list")

        all_class_names.add(cls)
        all_subclass_names.update(subs)

    return list(all_class_names - all_subclass_names)

