import threading
import collections.abc

def cachedmethod(cache, key=lambda self, func, args, kwargs: hash((func.__name__, tuple(args), frozenset(kwargs.items()), id(self))), lock=None):
    def decorator(func):
        @wraps(func)
        def wrapper(self, *args, **kwargs):
            # Convert args to a tuple to ensure hashability
            args = tuple(args) if isinstance(args, collections.abc.Sequence) else args
            cache_key = key(self, func, args, kwargs)

            if lock is None:
                lock = threading.Lock()

            with lock:
                if cache_key in cache:
                    return cache[cache_key]
                result = func(self, *args, **kwargs)
                cache[cache_key] = result
                return result
        return wrapper
    return decorator

