        self._keys = deque()
        self._values = {}

    def __setitem__(self, key: Any, value: Any) -> None:
        if key not in self._values:
            self._keys.append(key)
        self._values[key] = value

    def popitem(self) -> Tuple[Any, Any]:
        if not self._keys:
            raise KeyError("popitem(): dictionary is empty")
        key = self._keys.popleft()
        value = self._values.pop(key)
        return key, value

    def __getitem__(self, key: Any) -> Any:
        return self._values[key]

    def __delitem__(self, key: Any) -> None:
        if key in self._values:
            self._keys.remove(key)
            del self._values[key]

    def __len__(self) -> int:
        return len(self._values)

from collections import defaultdict
from functools import wraps

def lfu_cache(maxsize=128, typed=False):
    def decorating_function(user_function):
        cache = {}
        use_count = defaultdict(int)

        @wraps(user_function)
        def wrapper(*args, **kwargs):
            key = args
            if typed:
                key += tuple(sorted(kwargs.items()))
                key += tuple(type(v) for v in args)
                key += tuple(type(v) for v in kwargs.values())

            if key in cache:
                use_count[key] += 1
                return cache[key]

            result = user_function(*args, **kwargs)
            cache[key] = result
            use_count[key] += 1

            if len(cache) > maxsize:
                least_used_key = min(use_count, key=use_count.get)
                del cache[least_used_key]
                del use_count[least_used_key]

            return result

        return wrapper
    return decorating_function

class LFU:
    def __init__(self):
        self.frequency_map = {}
        self.keys_by_frequency = {}
        self.min_frequency = 0

    def _update_min_frequency(self):
        while self.min_frequency not in self.keys_by_frequency or not self.keys_by_frequency[self.min_frequency]:
            self.min_frequency += 1

    def popitem(self):
        if not self.frequency_map:
            return None

        self._update_min_frequency()

        keys = self.keys_by_frequency[self.min_frequency]
        key = keys.pop(0)

        if not keys:
            del self.keys_by_frequency[self.min_frequency]

        value = self.frequency_map.pop(key)
        return key, value

    def add(self, key, value):
        if key in self.frequency_map:
            self._remove_key(key)
        self.frequency_map[key] = value
        self.keys_by_frequency.setdefault(1, []).append(key)
        self.min_frequency = 1

    def _remove_key(self, key):
        freq = self.frequency_map[key]
        self.keys_by_frequency[freq].remove(key)
        if not self.keys_by_frequency[freq]:
            del self.keys_by_frequency[freq]
        del self.frequency_map[key]

    def increment_frequency(self, key):
        if key not in self.frequency_map:
            return

        self._remove_key(key)
        freq = self.frequency_map[key] + 1
        self.frequency_map[key] = freq
        self.keys_by_frequency.setdefault(freq, []).append(key)
        if freq > self.min_frequency:
            self.min_frequency = freq

from collections import OrderedDict

def lru_cache(maxsize=128, typed=False):
    if not isinstance(maxsize, int) or maxsize < 1:
        raise TypeError('maxsize must be a positive integer')

    def make_key(args, kwargs):
        key = args
        if typed:
            key += tuple(sorted(kwargs.items()))
            key += tuple(type(arg) for arg in args)
            key += tuple(type(value) for _, value in sorted(kwargs.items()))
        else:
            key += tuple(sorted(kwargs.items()))
        return key

    def decorator(func):
        cache = OrderedDict()

        def wrapper(*args, **kwargs):
            key = make_key(args, kwargs)

            if key in cache:
                cache.move_to_end(key)
                return cache[key][0]

            result = func(*args, **kwargs)
            cache[key] = (result, 0)

            if len(cache) > maxsize:
                oldest = next(iter(cache))
                del cache[oldest]

            cache.move_to_end(key)
            return result

        return wrapper

    return decorator

