import time
from collections import OrderedDict
from functools import wraps

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    def decorator(func):
        cache = OrderedDict()
        expiration_times = {}

        def make_key(args, kwargs):
            key = args
            if typed:
                key += tuple(sorted(kwargs.items(), key=lambda item: item[0]))
            else:
                key += tuple(kwargs.items())
            return key

        def is_expired(key):
            return timer() > expiration_times[key]

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = make_key(args, kwargs)
            current_time = timer()

            # Clean up expired items
            expired_keys = [k for k in expiration_times if is_expired(k)]
            for k in expired_keys:
                cache.pop(k, None)
                expiration_times.pop(k, None)

            if key in cache:
                cache.move_to_end(key)
                return cache[key]

            if len(cache) >= maxsize:
                cache.popitem(last=False)
                expiration_times.popitem(last=False)

            result = func(*args, **kwargs)
            cache[key] = result
            expiration_times[key] = current_time + ttl
            return result

        return wrapper

    return decorator

