import math

def round_half_to_even(n):
    integer_part, fractional_part = math.modf(n)
    if abs(fractional_part) < 0.5:
        return int(integer_part)
    elif abs(fractional_part) > 0.5:
        return int(integer_part) + (1 if integer_part > 0 else -1)
    else:
        # Handle the case of exactly 0.5 or -0.5
        return int(integer_part + 0.5) if int(integer_part + 0.5) % 2 == 0 else int(integer_part) + (1 if integer_part > 0 else -1)

from datetime import timedelta, timezone

class Time:
    NANOS_IN_A_DAY = 24 * 60 * 60 * 1_000_000_000

    def __init__(self, hour: int, minute: int, second: int, microsecond: int, tzinfo: timezone = None):
        self.hour = hour
        self.minute = minute
        self.second = second
        self.microsecond = microsecond
        self.tzinfo = tzinfo

    @classmethod
    def from_ticks(cls, ticks: int, tz: timezone = None):
        if not (0 <= ticks < cls.NANOS_IN_A_DAY):
            raise ValueError(f"ticks is out of bounds (0 <= ticks < {cls.NANOS_IN_A_DAY})")

        total_seconds = ticks // 1_000_000_000
        microseconds = (ticks % 1_000_000_000) * 1000

        time_of_day = timedelta(seconds=total_seconds, microseconds=microseconds)
        if time_of_day >= timedelta(days=1):
            time_of_day -= timedelta(days=1)

        hour = time_of_day.seconds // 3600
        minute = (time_of_day.seconds % 3600) // 60
        second = time_of_day.seconds % 60

        return cls(hour, minute, second, time_of_day.microseconds, tz)

