import os

def strip_root(path, root):
    if not path or not root:
        raise ValueError("Path and root must be non-empty strings")

    if not os.path.isabs(root):
        raise ValueError("Root must be an absolute path")

    if not os.path.isdir(root):
        raise ValueError("Root must be a directory")

    if not path.startswith(root):
        raise ValueError(f"Path '{path}' does not start with the root '{root}'")

    stripped_path = os.path.relpath(path, root)

    if os.path.normpath(os.path.join(root, stripped_path))!= os.path.normpath(path):
        raise ValueError("Path does not correctly resolve to the original path when joined with root")

    return stripped_path

