from typing import List, Optional

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not alphabet:
        raise ValueError("Alphabet must not be empty")

    base = len(alphabet)
    if number == 0:
        converted_string = alphabet[0]
    else:
        converted_string = []
        while number > 0:
            number, remainder = divmod(number, base)
            converted_string.append(alphabet[remainder])
        converted_string.reverse()
        converted_string = ''.join(converted_string)

    if padding is not None and len(converted_string) < padding:
        converted_string = converted_string.rjust(padding, alphabet[0])

    return converted_string

