from datetime import timedelta

def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None

    try:
        number, timeunit = frequency.split()
        number = int(number)
        timeunit = timeunit.lower()

        time_units = {
            "weeks": lambda n: timedelta(weeks=n),
            "days": lambda n: timedelta(days=n),
            "hours": lambda n: timedelta(hours=n),
            "minutes": lambda n: timedelta(minutes=n),
            "seconds": lambda n: timedelta(seconds=n)
        }

        if timeunit in time_units:
            return time_units[timeunit](number)
        elif timeunit == "months":
            return timedelta(days=number * 30)  # Approximation
        elif timeunit == "years":
            return timedelta(days=number * 365)  # Approximation
        else:
            raise ValueError("Invalid time unit in frequency")

    except (ValueError, AttributeError):
        raise ValueError("Invalid frequency format")

import socket

LOOPBACK_IP = '127.0.0.1'
LOCAL_HOSTS = ['localhost', LOOPBACK_IP]

def is_localhost(host):
    if not isinstance(host, str):
        return False

    if host in LOCAL_HOSTS:
        return True

    try:
        host_ip = socket.gethostbyname(host)
        if host_ip == LOOPBACK_IP:
            return True
        local_ips = socket.gethostbyname_ex(socket.gethostname())[2]
        if host_ip in local_ips:
            return True
    except socket.gaierror:
        return False

    return False

