def gaussian(x, u=0.2, sigma=0.1):
    two_pi = 2 * math.pi
    factor = 1 / (sigma * math.sqrt(two_pi))
    z = (x - u) / sigma
    return factor * math.exp(-0.5 * z ** 2)

