def load_configurations(config_filenames, overrides=None, resolve_env=True):
    if overrides is None:
        overrides = {}

    config_dict = {}
    error_records = []

    for filename in config_filenames:
        try:
            with open(filename, 'r') as file:
                config_data = file.read()

            if resolve_env:
                config_data = os.path.expandvars(config_data)

            config = json.loads(config_data)

            # Merge overrides
            config = {**config, **overrides}

            config_dict[filename] = config

        except (PermissionError, FileNotFoundError) as e:
            logging.error(f"File error ({filename}): {e}")
            error_records.append(e)

        except json.JSONDecodeError as e:
            logging.error(f"JSON decode error ({filename}): {e}")
            error_records.append(e)

        except Exception as e:
            logging.error(f"Unexpected error ({filename}): {e}")
            error_records.append(e)

    return config_dict, error_records

