                pass
    return conditionally_required_args

def are_args_within_length(self, args, max_length):
    if not isinstance(max_length, int) or max_length < 0:
        raise ValueError("max_length must be a non-negative integer")

    if not hasattr(args, '__iter__'):
        raise TypeError("args must be iterable")

    for arg in args:
        if not isinstance(arg, str):
            raise TypeError("All elements in args must be strings")
        if len(arg) > max_length:
            return False
    return True

class Validator:
    def __init__(self, choices):
        self.choices = choices

    def validate_choices_args(self, args):
        if not isinstance(args, (list, tuple)):
            raise TypeError("args must be a list or tuple")

        invalid_choices = [arg for arg in args if arg not in self.choices]

        if invalid_choices:
            raise ValueError(
                f"Invalid choices: {', '.join(invalid_choices)}. "
                f"Available choices are: {', '.join(self.choices)}"
            )

# Example usage:
