# validator.validate_choices_args(['option1', 'option4'])

def validate_min_max_args(self, args):
    if not isinstance(args, list):
        return False
    for arg in args:
        if not isinstance(arg, dict):
            return False
        if not all(k in arg for k in ('value','min','max')):
            return False
        try:
            if not (arg['min'] <= arg['value'] <= arg['max']):
                return False
        except (TypeError, ValueError):
            return False
    return True

def execute_complex_argument_type(self, subcommand, type_name, option_name, spec_option):
    complex_type_func = COMPLEX_TYPES.get(type_name)
    if not complex_type_func:
        available_types = ', '.join(COMPLEX_TYPES.keys())
        raise ValueError(f"Unknown complex type: '{type_name}'. Available types: {available_types}")

    return complex_type_func(option_name, self.vars, self.defaults, self.plugin_path, subcommand, spec_option)

def get_nested_custom_and_control_args(self, args):
    CONTROL_PREFIX = '--control-'
    CUSTOM_PREFIX = '--custom-'

    control_args = {}
    nested_args = {}
    custom_args = {}

    for arg in args:
        if arg.startswith(CONTROL_PREFIX):
            key = arg[len(CONTROL_PREFIX):]
            control_args[key] = True
        elif arg.startswith(CUSTOM_PREFIX):
            try:
                key, value = arg[len(CUSTOM_PREFIX):].split('=', 1)
                custom_args[key] = value
            except ValueError:
                raise ValueError(f"Invalid custom argument format: {arg}")
        else:
            try:
                key, value = arg.split('=', 1)
                if key in custom_args:
                    nested_args[key] = custom_args[key]
                else:
                    nested_args[key] = value
            except ValueError:
                raise ValueError(f"Invalid argument format: {arg}")

    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")

    if extra_vars is None:
        return vars_dict

    if not isinstance(extra_vars, dict):
        raise TypeError("extra_vars must be a dictionary or None")

    for key, value in extra_vars.items():
        if key in vars_dict and isinstance(vars_dict[key], dict) and isinstance(value, dict):
            vars_dict[key] = merge_extra_vars(vars_dict[key], value)
        else:
            vars_dict[key] = value

    return vars_dict

import subprocess
import json

def construct_ansible_args(playbook_path, verbose, extra_vars, ansible_args):
    args = ['ansible-playbook', playbook_path]

    if verbose is not None:
        args.extend(['-v'] * verbose)

    if extra_vars is not None:
        args.extend(['-e', json.dumps(extra_vars)])

    if ansible_args:
        for key, value in ansible_args.items():
            args.append(f'--{key}')
            if value is not True:
                args.append(str(value))

    return args

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    args = construct_ansible_args(playbook_path, verbose, extra_vars, ansible_args)

    result = subprocess.run(args, capture_output=True, text=True)

    if result.returncode!= 0:
        raise Exception(f"Ansible playbook failed with error: {result.stderr.strip()}")

    return result.stdout.strip()

import subprocess
import json

def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    try:
        vars_json = json.dumps(vars_dict)
    except (TypeError, ValueError):
        raise ValueError("vars_dict contains non-serializable data")

    command = ['ansible-playbook'] + cli_args + ['-e', vars_json]

    try:
        result = subprocess.run(command, capture_output=True, text=True, check=True)
    except subprocess.CalledProcessError as e:
        raise RuntimeError("Ansible playbook execution failed") from e

    return {
       'stdout': result.stdout,
       'stderr': result.stderr,
       'returncode': result.returncode
    }

class ArgumentConverter:
    def __init__(self):
        self.type_mappings = {
           'main': {'arg1': int, 'arg2': float},
            'virsh': {'arg1': str, 'arg2': bool},
            'ospd': {'arg1': list, 'arg2': dict}
        }

    def _convert_non_cli_args(self, parser_name, values_dict):
        if not isinstance(parser_name, str) or not isinstance(values_dict, dict):
            raise ValueError("Invalid input types")

        if parser_name not in self.type_mappings:
            raise ValueError(f"Unknown parser name: {parser_name}")

        for arg, cast_type in self.type_mappings[parser_name].items():
            if arg in values_dict:
                try:
                    values_dict[arg] = cast_type(values_dict[arg])
                except (ValueError, TypeError) as e:
                    print(f"Failed to convert {arg}: {e}")

import os
import yaml

def get_plugin_spec_flatten_dict(plugin_dir):
    yaml_extensions = ['.yaml', '.yml']
    result = {}

    if not os.path.isdir(plugin_dir):
        raise ValueError(f"Provided path '{plugin_dir}' is not a valid directory.")

    for file in os.listdir(plugin_dir):
        if any(file.endswith(ext) for ext in yaml_extensions):
            file_path = os.path.join(plugin_dir, file)
            try:
                with open(file_path, 'r') as stream:
                    data = yaml.safe_load(stream)
                    if data is None:
                        continue
                    flatten_dict(data, result, prefix=file.split('.')[0] + '_')
            except yaml.YAMLError as exc:
                print(f"Error reading {file}: {exc}")

    return result

def flatten_dict(d, result, prefix=''):
    for key, value in d.items():
        new_key = prefix + key
        if isinstance(value, dict):
            flatten_dict(value, result, prefix=new_key + '_')
        else:
            result[new_key] = value

