MAGIC_ENV_TAG = 'Magic_ENV_TAG'

class RequestType:
    def __init__(self, body: str, content_type: str):
        self.body = body
        self.content_type = content_type

def has_valid_content(request: RequestType) -> bool:
    if request.content_type == JSON_CONTENT_TYPE:
        try:
            data = json.loads(request.body)
            return 'events' in data
        except json.JSONDecodeError:
            return False
    elif request.content_type == XML_CONTENT_TYPE:
        try:
            root = ET.fromstring(request.body)
            return root.tag == MAGIC_ENV_TAG
        except ET.ParseError:
            return False
    return False

