def apply_timezone_if_missing(dt, default_tz=UTC):
    if dt.tzinfo is None:
        return dt.replace(tzinfo=default_tz)
    return dt

def format_dt(dt, format_string='%Y-%m-%d %H:%M:%S %Z%z'):
