    return dt.strftime(format_string)

from typing import Set, Tuple, Callable, Optional

CODE_BLOCK_MARKER = '```'
TAG_PREFIX = '#'

def find_tags(text: str, replacer: Optional[Callable[[str], str]] = None) -> Tuple[Set[str], str]:
    in_code_block = False
    tags = set()
    result = []
    index = 0

    while index < len(text):
        if text[index:index + len(CODE_BLOCK_MARKER)] == CODE_BLOCK_MARKER:
            in_code_block = not in_code_block
            result.append(text[index:index + len(CODE_BLOCK_MARKER)])
            index += len(CODE_BLOCK_MARKER)
        elif text[index] == TAG_PREFIX and not in_code_block:
            start_index = index + 1
            while start_index < len(text) and (text[start_index].isalnum() or text[start_index] == '_'):
                start_index += 1
            tag = text[index + 1:start_index]
            tags.add(tag)
            if replacer:
                replaced = replacer(tag)
                result.append(text[index:start_index].replace(tag, replaced))
            else:
                result.append(text[index:start_index])
            index = start_index
        else:
            result.append(text[index])
            index += 1

    return tags, ''.join(result)

