from xml.etree.ElementTree import Element

def xml_children_as_dict(node: Element) -> dict:
    result = {}
    for child in node:
        tag = child.tag
        if tag not in result:
            result[tag] = child if len(node) == 1 else [child]
        elif isinstance(result[tag], list):
            result[tag].append(child)
    return result

