def get_nodeinfo_well_known_document(url: str, document_path: Optional[str] = None) -> Dict[str, Union[str, Dict]]:
    if document_path is None:
        document_path = '/.well-known/document'

    full_url = url + document_path

    try:
        response = requests.get(full_url)
        response.raise_for_status()

        content_type = response.headers.get('Content-Type', '')
        if 'application/json' in content_type:
            content = response.json()
        elif 'text/' in content_type:
            content = response.text
        else:
            content = response.content

        return {
            'url': url,
            'document_path': document_path,
            'content': content
        }
    except requests.exceptions.RequestException as e:
        return {
            'url': url,
            'document_path': document_path,
            'error': str(e)
        }

from lxml import etree
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.asymmetric import padding
from cryptography.hazmat.primitives.serialization import load_pem_public_key

def verify_relayable_signature(public_key_pem, doc, signature):
    namespaces = {'ds': 'http://www.w3.org/2000/09/xmldsig#'}

    public_key = load_pem_public_key(public_key_pem)
    root = etree.fromstring(doc)

    signature_element = root.find('.//ds:Signature', namespaces)
    if signature_element is None:
        return False

    signed_info = extract_signed_info(signature_element, namespaces)
    signed_info_str = canonicalize(signed_info)

    reference = find_reference(signature_element, namespaces)
    if reference is None:
        return False

    xml_to_sign = strip_signature_element(root, signature_element)
    xml_to_sign_bytes = etree.tostring(xml_to_sign, method='c14n')

    signature_bytes = bytes.fromhex(signature)

    try:
        public_key.verify(
            signature_bytes,
            xml_to_sign_bytes,
            padding.PKCS1v15(),
            get_hash_algorithm(signature_element)
        )
        return True
    except Exception:
        return False

def extract_signed_info(signature_element, namespaces):
    return signature_element.find('.//ds:SignedInfo', namespaces)

def canonicalize(signed_info):
    return etree.tostring(signed_info, method='c14n')

def find_reference(signature_element, namespaces):
    return signature_element.find('.//ds:Reference', namespaces)

def strip_signature_element(root, signature_element):
    transforms = signature_element.find('.//ds:Transforms', namespaces)
    if transforms is not None:
        for transform in transforms:
            if transform.get('Algorithm') == 'http://www.w3.org/2000/09/xmldsig#enveloped-signature':
                root.remove(signature_element)
    return root

def get_hash_algorithm(signature_element):
    signature_method = signature_element.find('.//ds:SignatureMethod', namespaces)
    algorithm = signature_method.get('Algorithm')
    if algorithm == 'http://www.w3.org/2001/04/xmldsig-more#rsa-sha256':
        return hashes.SHA256()
    # Add more algorithm checks as needed
    return hashes.SHA1()  # Default or fallback

