HOST_META_PATH = '/.well-known/host-meta'

def retrieve_diaspora_host_meta(host):
    if not isinstance(host, str) or not host:
        raise ValueError("Invalid host provided")

    url = f"https://{host}{HOST_META_PATH}"
    try:
        response = requests.get(url)
        response.raise_for_status()
        root = ET.fromstring(response.content)
        return XRD(root)
    except (requests.RequestException, ET.ParseError):
        return None

import requests

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    valid_methods = {"get", "post", "put", "delete", "patch", "options", "head"}
    method = method.lower()

    if method not in valid_methods:
        raise ValueError(f"Invalid HTTP method: {method}")

    try:
        if method == "post":
            response = requests.post(url, data=data, timeout=timeout, *args, **kwargs)
        elif method == "get":
            response = requests.get(url, params=data, timeout=timeout, *args, **kwargs)
        elif method == "put":
            response = requests.put(url, data=data, timeout=timeout, *args, **kwargs)
        elif method == "delete":
            response = requests.delete(url, data=data, timeout=timeout, *args, **kwargs)
        elif method == "patch":
            response = requests.patch(url, data=data, timeout=timeout, *args, **kwargs)
        elif method == "options":
            response = requests.options(url, data=data, timeout=timeout, *args, **kwargs)
        elif method == "head":
            response = requests.head(url, data=data, timeout=timeout, *args, **kwargs)
        return response
    except requests.exceptions.RequestException as e:
        raise SystemError(f"Request failed: {e}")
